const D = { density:.5, scale:1, energy:.6, speed:1, hue:44, glow:.5, x:.5, y:.5, style:'gilt', seed:0, alpha:100, act:'inflate' };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const u = Math.min(width, height);
const st = P.style;
const intn = (K.intensity!=null?K.intensity:0.6);
const fr = i => { const s = Math.sin(i*127.1 + P.seed*311.7)*43758.5453; return s - Math.floor(s); };

const depth = 3 + Math.round(Math.max(0,Math.min(1,P.density))*2);   // 3..5 -> 130..890 tris
const diag = Math.hypot(width,height);
const BW = Math.min(2048, Math.ceil(diag*1.04));                     // oversize so slow rotation never voids
const key = [width,height,depth,st,P.seed,P.scale.toFixed(2),P.x.toFixed(2),P.y.toFixed(2)].join('|');

if (S.key !== key){
  S.key = key;
  const PHI = (1+Math.sqrt(5))/2;
  const ph0 = fr(1)*Math.PI*2;
  // seed wheel of 10 fat Robinson half-rhombi (fivefold sun); mirror alternate for seamless edges
  let tris = [];
  for (let i=0;i<10;i++){
    let B={x:Math.cos((2*i-1)*Math.PI/10+ph0), y:Math.sin((2*i-1)*Math.PI/10+ph0)};
    let C={x:Math.cos((2*i+1)*Math.PI/10+ph0), y:Math.sin((2*i+1)*Math.PI/10+ph0)};
    if (i%2===0){ const s=B; B=C; C=s; }
    tris.push([0,{x:0,y:0},B,C]);
  }
  // deflation (Preshing): fat -> 1 fat + 1 thin ; thin -> 2 thin + 1 fat
  for (let d=0; d<depth; d++){
    const out=[];
    for (let k=0;k<tris.length;k++){
      const T=tris[k], c=T[0], Aa=T[1], Bb=T[2], Cc=T[3];
      if (c===0){
        const Pp={x:Aa.x+(Bb.x-Aa.x)/PHI, y:Aa.y+(Bb.y-Aa.y)/PHI};
        out.push([0,Cc,Pp,Bb],[1,Pp,Cc,Aa]);
      } else {
        const Q={x:Bb.x+(Aa.x-Bb.x)/PHI, y:Bb.y+(Aa.y-Bb.y)/PHI};
        const R={x:Bb.x+(Cc.x-Bb.x)/PHI, y:Bb.y+(Cc.y-Bb.y)/PHI};
        out.push([1,R,Cc,Aa],[1,Q,R,Bb],[0,R,Q,Aa]);
      }
    }
    tris=out;
  }
  if (S.buf) S.buf.remove();
  S.buf = createGraphics(BW,BW); S.buf.pixelDensity(1); S.buf.colorMode(HSB,360,100,100,100);
  const g = S.buf;
  const CX = BW*0.5 + (P.x-0.5)*BW*0.22, CY = BW*0.5 + (P.y-0.5)*BW*0.22;
  const sc = BW*(0.46 + 0.30*P.scale);
  // opaque ground (never leave buffer transparent -> genart no-bed luminance)
  g.push(); g.noStroke();
  let bg;
  if (st==='blueprint') bg=[214,66,15];
  else if (st==='neon') bg=[262,52,6];
  else if (st==='riso') bg=[40,10,90];
  else if (st==='sumi') bg=[40,9,86];
  else bg=[252,58,13];                         // gilt: deep indigo/lapis
  g.background(bg[0],bg[1],bg[2]);
  const rg = g.drawingContext.createRadialGradient(CX,CY,BW*0.03, CX,CY,BW*0.62);
  if (st==='riso'||st==='sumi'){ rg.addColorStop(0,'rgba(255,255,255,0.05)'); rg.addColorStop(1,'rgba(60,40,10,0.16)'); }
  else { rg.addColorStop(0,'rgba(255,238,196,0.11)'); rg.addColorStop(1,'rgba(0,0,0,0.34)'); }
  g.drawingContext.fillStyle=rg; g.drawingContext.fillRect(0,0,BW,BW);
  g.pop();

  const cents=[];
  g.push();
  for (let k=0;k<tris.length;k++){
    const T=tris[k], c=T[0];
    const ax=CX+T[1].x*sc, ay=CY+T[1].y*sc;
    const bx=CX+T[2].x*sc, by=CY+T[2].y*sc;
    const cx=CX+T[3].x*sc, cy=CY+T[3].y*sc;
    const rr = Math.hypot((T[1].x+T[2].x+T[3].x)/3,(T[1].y+T[2].y+T[3].y)/3);
    const jt = fr(k*3+7);
    if (st==='gilt'){
      if (c===0){ g.fill((42+jt*8)%360, 60+jt*16, 52+rr*22+jt*14); }
      else { g.fill((30+jt*8)%360, 78+jt*12, 38+rr*16+jt*12); }
      g.noStroke();
      g.beginShape(); g.vertex(ax,ay); g.vertex(bx,by); g.vertex(cx,cy); g.endShape(CLOSE);
    } else if (st==='riso'){
      if (c===0){ g.fill(348, 58, 84, 82); } else { g.fill(190, 50, 80, 82); }
      g.noStroke();
      const ox = c===0?1.6:-1.6, oy=c===0?-1.6:1.6;   // fake ink misregistration
      g.beginShape(); g.vertex(ax+ox,ay+oy); g.vertex(bx+ox,by+oy); g.vertex(cx+ox,cy+oy); g.endShape(CLOSE);
    } else if (st==='blueprint'){
      g.fill(210, 60, 22, c===0?26:12); g.noStroke();
      g.beginShape(); g.vertex(ax,ay); g.vertex(bx,by); g.vertex(cx,cy); g.endShape(CLOSE);
    } else if (st==='neon'){
      g.fill((P.hue + (c?40:0))%360, 55, c?8:11); g.noStroke();
      g.beginShape(); g.vertex(ax,ay); g.vertex(bx,by); g.vertex(cx,cy); g.endShape(CLOSE);
    }
    // leading: stroke legs A->B and C->A, SKIP base B->C (merges half-rhombi into seamless rhombs)
    if (st==='gilt'){
      g.stroke(250,55,7,72); g.strokeWeight(Math.max(1,sc*0.006));
      g.line(ax,ay,bx,by); g.line(cx,cy,ax,ay);
    } else if (st==='blueprint'){
      g.stroke(200-rr*8, 66, 84, 48); g.strokeWeight(1);
      g.line(ax,ay,bx,by); g.line(cx,cy,ax,ay);
    } else if (st==='riso'){
      g.stroke(c===0?348:190, 44, 42, 30); g.strokeWeight(1);
      g.line(ax,ay,bx,by); g.line(cx,cy,ax,ay);
    } else if (st==='sumi'){
      const dry = 0.55+0.75*fr(k*5+2);
      g.stroke(34, 24, 16, 52+jt*36); g.strokeWeight(Math.max(0.8, sc*0.0075*dry));
      if (fr(k*7+3)>0.13){ g.line(ax,ay,bx,by); }
      if (fr(k*7+5)>0.13){ g.line(cx,cy,ax,ay); }
    } else if (st==='neon'){
      g.stroke((P.hue)%360, 60, 26, 40); g.strokeWeight(1);
      g.line(ax,ay,bx,by); g.line(cx,cy,ax,ay);
    }
    cents.push({x:(ax+bx+cx)/3 - BW*0.5, y:(ay+by+cy)/3 - BW*0.5, c:c, r:rr});
  }
  g.pop();
  if (st==='blueprint'){
    g.push(); g.noFill(); g.stroke(200,50,72,26); g.strokeWeight(1);
    for (let ci=1; ci<=5; ci++){ g.circle(CX,CY, sc*2*ci/5); }
    g.pop();
  }
  S.cents=cents; S.BW=BW; S.total=tris.length;
}

// ---------- live overlay (baked buffer + K.t motion floor) ----------
const rot = K.t*(0.008 + P.speed*0.011) * (P.act==='drift'?1.7:1.0);
const alphaMul = P.alpha/100;
push();
translate(width*0.5, height*0.5);
rotate(rot);
if (P.alpha<100) tint(0,0,100,P.alpha);
image(S.buf, -S.BW*0.5, -S.BW*0.5);
noTint();

// glow-front: an expanding ring re-lights tiles by radial order (continuous K.t -> never re-phases)
const front = (P.act==='drift') ? ((K.t*P.speed*0.05)%1.08) : ((K.t*P.speed*0.09) % 1.08);
const bw = 0.09 + P.glow*0.15 + (P.act==='pulse'?0.06:0);
const peak = 42 + P.energy*46;
const beatBloom = (K.pulse*0.5 + A.bass*0.9) * (P.act==='pulse'?2.0:1.0);
const shimmer = 0.5+0.5*Math.sin(K.t*0.6);
blendMode(ADD);
noStroke();
const cents=S.cents; let drawn=0;
for (let i=0;i<cents.length && drawn<150;i++){
  const tc=cents[i];
  const dd=Math.abs(tc.r-front);
  if (dd>=bw) continue;
  const amt = Math.max(0,1-dd/bw);
  const hx = (P.hue + tc.c*22 + tc.r*46 + K.section*20) % 360;
  const a = (0.06 + peak*0.006)*amt*(0.6+intn)*(0.55+0.45*shimmer) * alphaMul * 100 * 0.33;
  fill(hx, st==='neon'?70:44, 100, a);
  circle(tc.x, tc.y, u*0.045*(0.7+amt));
  drawn++;
}
// central sun beat bloom (partial-frame only -> never trips the strobe gate)
if (beatBloom>0.04){
  fill((P.hue+18)%360, 34, 100, Math.min(30, beatBloom*11)*alphaMul);
  circle(0,0, u*0.5*(1+beatBloom*0.18));
}
blendMode(BLEND);
drawingContext.shadowBlur=0;
pop();
